def check_n3_6_colors():
    # Let's try to find a 3x3 grid with 6 colors such that no 2x2 is a rainbow.
    # Colors: 0, 1, 2, 3, 4, 5
    # There are 9 squares.
    import itertools

    for p in itertools.product(range(6), repeat=9):
        grid = [p[0:3], p[3:6], p[6:9]]

        valid = True
        for r in range(2):
            for c in range(2):
                square = [grid[r][c], grid[r+1][c], grid[r][c+1], grid[r+1][c+1]]
                if len(set(square)) == 4:
                    valid = False
                    break
            if not valid: break

        if valid:
            # Check how many colors were used
            used_colors = set(p)
            if len(used_colors) == 6:
                return grid
    return None

print(check_n3_6_colors())

def find_min_X(n):
    import itertools

    # All 2x2 squares
    squares = []
    for r in range(n-1):
        for c in range(n-1):
            squares.append([(r, c), (r+1, c), (r, c+1), (r+1, c+1)])

    for k in range(1, n*n + 1):
        # Try all subsets of size k
        for subset in itertools.combinations([(r, c) for r in range(n) for c in range(n)], k):
            subset_set = set(subset)
            all_ok = True
            for sq in squares:
                count = 0
                for cell in sq:
                    if cell in subset_set:
                        count += 1
                if count < 2:
                    all_ok = False
                    break
            if all_ok:
                return k

print(find_min_X(2))
print(find_min_X(3))
print(find_min_X(4))
